public class ThymeleafViewRenderFragmentTests {

    private static final String CONTEXT_PATH = "/app";
    private static final Locale LOCALE = Locale.FRANCE;
    private static final String ENGINE_OUTPUT = "engine-output";

    private ThymeleafView view;
    private WebApplicationContext applicationContext;
    private ServletContext servletContext;
    private HttpServletRequest request;
    private HttpServletResponse response;
    private PrintWriter responseWriter;
    private StringWriter responseContent;
    private ISpringTemplateEngine templateEngine;

    @BeforeEach
    public void setUp() {
        this.servletContext = mock(ServletContext.class);
        when(this.servletContext.getContextPath()).thenReturn(CONTEXT_PATH);

        this.applicationContext = mock(WebApplicationContext.class);
        when(this.applicationContext.getServletContext()).thenReturn(this.servletContext);
        when(this.applicationContext.containsBean("requestDataValueProcessor")).thenReturn(Boolean.FALSE);

        this.request = mock(HttpServletRequest.class);
        when(this.request.getServletContext()).thenReturn(this.servletContext);
        when(this.request.getContextPath()).thenReturn(CONTEXT_PATH);
        when(this.request.getRequestURI()).thenReturn(CONTEXT_PATH + "/view");
        when(this.request.getAttribute(RequestContext.WEB_APPLICATION_CONTEXT_ATTRIBUTE))
                .thenReturn(this.applicationContext);

        this.response = mock(HttpServletResponse.class);
        this.responseContent = new StringWriter();
        this.responseWriter = new PrintWriter(this.responseContent);
        doReturn(this.responseWriter).when(this.response).getWriter();

        // A real configuration is required when a fragment ("template :: fragment") is parsed.
        final TemplateEngine configurationEngine = new TemplateEngine();
        configurationEngine.setDialect(new SpringStandardDialect());
        final IEngineConfiguration configuration = configurationEngine.getConfiguration();

        this.templateEngine = mock(ISpringTemplateEngine.class);
        when(this.templateEngine.getConfiguration()).thenReturn(configuration);
        when(this.templateEngine.getAllowedClassOverridesForViews())
                .thenReturn(Collections.<Class<?>>emptyList());
        doAnswer(invocation -> {
            final Writer writer = invocation.getArgument(3);
            writer.write(ENGINE_OUTPUT);
            writer.flush();
            return null;
        }).when(this.templateEngine).process(
                anyString(), org.mockito.ArgumentMatchers.<Set<String>>any(),
                any(IContext.class), any(Writer.class));

        this.view = new ThymeleafView();
        this.view.setServletContext(this.servletContext);
        this.view.setApplicationContext(this.applicationContext);
        this.view.setTemplateName("index");
        this.view.setLocale(LOCALE);
        this.view.setTemplateEngine(this.templateEngine);
    }


    @Test
    public void rendersTemplateWithoutFragmentAndWritesEngineOutput() throws Exception {
        final Map<String, Object> model = new HashMap<>();
        model.put("message", "hello");

        this.view.renderFragment(null, model, this.request, this.response);

        final ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        verify(this.templateEngine).process(
                eq("index"), isNull(), contextCaptor.capture(), any(Writer.class));

        assertEquals("hello", contextCaptor.getValue().getVariable("message"));
        assertEquals(LOCALE, contextCaptor.getValue().getLocale());
        verify(this.response).setLocale(LOCALE);
        verify(this.response).setContentType(AbstractThymeleafView.DEFAULT_CONTENT_TYPE);
        assertEquals(ENGINE_OUTPUT, this.responseContent.toString());
    }


    @Test
    public void mergesStaticPathVariableAndModelVariablesInOrder() throws Exception {
        this.view.addStaticVariable("shared", "from-static");
        this.view.addStaticVariable("staticOnly", "static-value");

        final Map<String, Object> pathVariables = new HashMap<>();
        pathVariables.put("shared", "from-path");
        pathVariables.put("pathOnly", "path-value");
        when(this.request.getAttribute(View.PATH_VARIABLES)).thenReturn(pathVariables);

        final Map<String, Object> model = new HashMap<>();
        model.put("shared", "from-model");
        model.put("modelOnly", "model-value");

        this.view.renderFragment(null, model, this.request, this.response);

        final ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        verify(this.templateEngine).process(
                eq("index"), isNull(), contextCaptor.capture(), any(Writer.class));

        final IContext context = contextCaptor.getValue();
        assertEquals("from-model", context.getVariable("shared"));
        assertEquals("static-value", context.getVariable("staticOnly"));
        assertEquals("path-value", context.getVariable("pathOnly"));
        assertEquals("model-value", context.getVariable("modelOnly"));
    }


    @Test
    public void exposesSpringRequestContextAndEvaluationContextVariables() throws Exception {
        this.view.renderFragment(null, null, this.request, this.response);

        final ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        verify(this.templateEngine).process(
                eq("index"), isNull(), contextCaptor.capture(), any(Writer.class));

        final IContext context = contextCaptor.getValue();
        final Object springRequestContext = context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT);
        assertTrue(springRequestContext instanceof RequestContext);
        assertSame(springRequestContext,
                context.getVariable(AbstractTemplateView.SPRING_MACRO_REQUEST_CONTEXT_ATTRIBUTE));
        assertTrue(context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT)
                instanceof SpringWebMvcThymeleafRequestContext);
        assertNotNull(context.getVariable(
                ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME));
    }


