    @Test
    public void rejectsMissingTemplateName() {
        this.view.setTemplateName(null);

        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> this.view.renderFragment(null, null, this.request, this.response));

        assertEquals("Property 'templateName' is required", exception.getMessage());
    }


    @Test
    public void rejectsMissingLocale() {
        this.view.setLocale(null);

        final IllegalArgumentException exception = assertThrows(
