                () -> this.view.renderFragment(null, null, this.request, this.response));

        assertEquals("Property 'locale' is required", exception.getMessage());
    }


    @Test
    public void rejectsMissingTemplateEngine() {
        this.view.setTemplateEngine(null);

        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> this.view.renderFragment(null, null, this.request, this.response));

        assertEquals("Property 'templateEngine' is required", exception.getMessage());
    }


    @Test
    public void respectsForcedContentTypeAndCharacterEncoding() throws Exception {
        this.view.setForceContentType(true);
        this.view.setContentType("application/json");
        this.view.setCharacterEncoding("UTF-8");

        this.view.renderFragment(null, null, this.request, this.response);

        verify(this.response).setContentType("application/json");
        verify(this.response).setCharacterEncoding("UTF-8");
    }


    @Test
    public void usesNegotiatedContentTypeWhenNotForced() throws Exception {
        when(this.request.getAttribute(View.SELECTED_CONTENT_TYPE)).thenReturn(MediaType.APPLICATION_JSON);

        this.view.renderFragment(null, null, this.request, this.response);

        verify(this.response).setContentType("application/json");
    }


    @Test
    public void passesResponseWriterDirectlyWhenProducingPartialOutput() throws Exception {
        this.view.setProducePartialOutputWhileProcessing(true);

        this.view.renderFragment(null, null, this.request, this.response);

        final ArgumentCaptor<Writer> writerCaptor = ArgumentCaptor.forClass(Writer.class);
        verify(this.templateEngine).process(
                eq("index"), isNull(), any(IContext.class), writerCaptor.capture());
        assertSame(this.responseWriter, writerCaptor.getValue());
        verify(this.response, times(1)).getWriter();
        assertEquals(ENGINE_OUTPUT, this.responseContent.toString());
    }


    @Test
    public void buffersOutputAndWritesItToResponseWhenNotProducingPartialOutput() throws Exception {
        this.view.setProducePartialOutputWhileProcessing(false);

        this.view.renderFragment(null, null, this.request, this.response);

        final ArgumentCaptor<Writer> writerCaptor = ArgumentCaptor.forClass(Writer.class);
        verify(this.templateEngine).process(
                eq("index"), isNull(), any(IContext.class), writerCaptor.capture());
        assertNotSame(this.responseWriter, writerCaptor.getValue());
        assertEquals(ENGINE_OUTPUT, this.responseContent.toString());
        verify(this.response, times(2)).getWriter();
        verify(this.responseWriter).flush();
    }

