        pathVariables.put("pathVariable", "from-path");
        pathVariables.put("sharedVariable", "from-path");
        exchange.getAttributes().put(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE, pathVariables);

        final ThymeleafReactiveView view = newView(engine);
        view.setTemplateName("home");
        view.addStaticVariable("staticVariable", "from-static");
        view.addStaticVariable("sharedVariable", "from-static");

        final Map<String, Object> renderAttributes = new HashMap<>();
        renderAttributes.put("modelVariable", "from-model");
        renderAttributes.put("sharedVariable", "from-model");

