                new StandardExpressionParser());
        when(this.engineConfiguration.getExecutionAttributes()).thenReturn(executionAttributes);

        this.templateEngine = mock(ISpringTemplateEngine.class);
        when(this.templateEngine.getConfiguration()).thenReturn(this.engineConfiguration);
        when(this.templateEngine.getAllowedClassOverridesForViews()).thenReturn(Collections.emptyList());

        this.view = new ThymeleafView("home");
        this.view.setApplicationContext(this.webApplicationContext);
        this.view.setServletContext(this.servletContext);
        this.view.setTemplateEngine(this.templateEngine);
        this.view.setLocale(Locale.CANADA_FRENCH);
