    @Test
    public void mergesModelAndExposesSpringAndThymeleafContextVariables() throws Exception {
        this.view.addStaticVariable("staticOnly", "static");
        this.view.addStaticVariable("shared", "static");
        this.requestAttributes.put(View.PATH_VARIABLES, Map.of(
                "pathOnly", "path",
                "shared", "path"));

        final Map<String, Object> model = new HashMap<String, Object>();
        model.put("modelOnly", "model");
        model.put("shared", "model");

        final RenderCapture capture = renderAndCapture(
                "home", null, Collections.emptySet(), model);

        assertEquals("static", capture.context.getVariable("staticOnly"));
        assertEquals("path", capture.context.getVariable("pathOnly"));
        assertEquals("model", capture.context.getVariable("modelOnly"));
        assertEquals("model", capture.context.getVariable("shared"));

        assertInstanceOf(RequestContext.class,
                capture.context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));
        assertInstanceOf(RequestContext.class,
                capture.context.getVariable(AbstractTemplateView.SPRING_MACRO_REQUEST_CONTEXT_ATTRIBUTE));
        assertInstanceOf(SpringWebMvcThymeleafRequestContext.class,
                capture.context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT));
        assertInstanceOf(ThymeleafEvaluationContext.class,
                capture.context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME));

        assertEquals(Locale.CANADA_FRENCH, capture.context.getLocale());
        verify(this.response).setLocale(Locale.CANADA_FRENCH);
        verify(this.response).setContentType(ThymeleafView.DEFAULT_CONTENT_TYPE);
        assertSame(this.responseWriter, capture.writer);
        assertEquals("rendered", this.responseBody.toString());
