/**
 * Tests for {@link ProcessorTemplateHandler#handleStandaloneElement(IStandaloneElementTag)}.
 *
 * These tests invoke the target method directly. This keeps each test focused on one
 * of the branches of this comparatively large handler method while still using the
 * real model controller, processor iterator and structure handlers.
 */
class ProcessorTemplateHandlerHandleStandaloneElementTests {


    @Test
    @DisplayName("A stopped throttle queues the event without touching the rest of the handler chain")
    void queuesEventWhenThrottlingHasStoppedProcessing() {
        final Fixture fixture = new Fixture(true);
        final IStandaloneElementTag tag = fixture.parse("<mytag />");

        fixture.flowController.stopProcessing = true;
        fixture.handler.handleStandaloneElement(tag);

        assertTrue(fixture.next.events.isEmpty(), "The event must not be delegated while processing is stopped");
        assertTrue(fixture.flowController.processorTemplateHandlerPending, "The queued event must mark the handler as pending");
        assertEquals(0, fixture.context.level(), "Queueing must happen before the context level is increased");

        fixture.flowController.stopProcessing = false;
        fixture.handler.handlePending();

        assertEvents(fixture, "standalone:mytag");
        assertFalse(fixture.flowController.processorTemplateHandlerPending);
        assertEquals(0, fixture.context.level(), "Pending processing must leave the context level balanced");
    }


    @Test
    @DisplayName("A standalone tag without processors is delegated unchanged")
    void delegatesStandaloneElementWithoutAssociatedProcessors() {
        final Fixture fixture = new Fixture(false);
        final IStandaloneElementTag tag = fixture.parse("<mytag />");

        fixture.handler.handleStandaloneElement(tag);

        assertEvents(fixture, "standalone:mytag");
        assertEquals(0, fixture.context.level());
    }


    @Test
    @DisplayName("A throttled standalone tag without processors still delegates and completes pending work")
    void delegatesStandaloneElementWithoutProcessorsWhenThrottled() {
        final Fixture fixture = new Fixture(true);
        final IStandaloneElementTag tag = fixture.parse("<mytag />");

        fixture.handler.handleStandaloneElement(tag);

        assertEvents(fixture, "standalone:mytag");
        assertEvents(fixture, "standalone:mytag");
        assertFalse(fixture.flowController.processorTemplateHandlerPending);
        assertEquals(0, fixture.context.level());
    }


    @Test
    @DisplayName("Attribute processors associated with a standalone tag are executed")
    void executesProcessorAssociatedThroughAttribute() {
        final Fixture fixture = new Fixture(false,
                attributeTagProcessor("replace", 10,
                        (context, tag, handler) -> handler.replaceWith("attribute-result", false)));

        fixture.handler.handleStandaloneElement(fixture.parse("<mytag replace=\"yes\" />"));

        assertEvents(fixture, "text:attribute-result");
        assertEquals(0, fixture.context.level());
    }


    @Test
    @DisplayName("replaceWith(text) discards the original standalone event")
    void replacesStandaloneElementWithText() {
        final Fixture fixture = new Fixture(false,
                elementTagProcessor("mytag", 10,
                        (context, tag, handler) -> handler.replaceWith("replacement", false)));

        fixture.handler.handleStandaloneElement(fixture.parse("<mytag />"));

        assertEvents(fixture, "text:replacement");
        assertEquals(0, fixture.context.level());
    }


    @Test
    @DisplayName("replaceWith(model) queues every event in the replacement model")
    void replacesStandaloneElementWithModel() {
        final Fixture fixture = new Fixture(false,
                elementTagProcessor("mytag", 10, (context, tag, handler) -> {
                    final IModel replacement = context.getModelFactory().createModel();
                    replacement.add(context.getModelFactory().createText("first"));
                    replacement.add(context.getModelFactory().createText("second"));
                    handler.replaceWith(replacement, false);
                }));

        fixture.handler.handleStandaloneElement(fixture.parse("<mytag />"));

        assertEvents(fixture, "text:first", "text:second");
        assertEquals(0, fixture.context.level());
    }


    @Test
    @DisplayName("setBody(text) turns a standalone tag into open/text/close events")
    void setsBodyTextOnStandaloneElement() {
        final Fixture fixture = new Fixture(false,
                elementTagProcessor("mytag", 10,
                        (context, tag, handler) -> handler.setBody("body-text", false)));

        fixture.handler.handleStandaloneElement(fixture.parse("<mytag />"));

        assertEvents(fixture, "open:mytag", "text:body-text", "close:mytag");
        assertEquals(0, fixture.context.level());
    }


    @Test
    @DisplayName("setBody(model) turns a standalone tag into open/model/close events")
    void setsBodyModelOnStandaloneElement() {
        final Fixture fixture = new Fixture(false,
                elementTagProcessor("mytag", 10, (context, tag, handler) -> {
                    final IModel body = context.getModelFactory().createModel();
                    body.add(context.getModelFactory().createText("model-body"));
                    handler.setBody(body, false);
