@Test
@DisplayName("An element model processor receives the gathered standalone tag and can replace it")
void elementModelProcessorProcessesGatheredStandaloneModel() {
    final AtomicInteger invocations = new AtomicInteger();
    final Fixture fixture = new Fixture(false,
            elementModelProcessor("mytag", 10, (context, model, handler) -> {
                invocations.incrementAndGet();
                assertEquals(1, model.size());
                assertInstanceOf(IStandaloneElementTag.class, model.get(0));
                assertEquals("mytag", ((IStandaloneElementTag) model.get(0)).getElementCompleteName());
                model.replace(0, context.getModelFactory().createText("model-processor-result"));
            }));

    fixture.handler.handleStandaloneElement(fixture.parse("<mytag />"));

    assertEquals(1, invocations.get(), "The model processor must be executed exactly once");
    assertEvents(fixture, "text:model-processor-result");
    assertEquals(0, fixture.context.level());
}


@Test
@DisplayName("A no-op element model processor leaves the original standalone tag in place")
void noOpElementModelProcessorDelegatesOriginalTag() {
    final AtomicInteger invocations = new AtomicInteger();
