            elementModelProcessor("mytag", 10, (context, model, handler) -> {
                invocations.incrementAndGet();
                assertEquals(1, model.size());
                assertInstanceOf(IStandaloneElementTag.class, model.get(0));
            }));

    fixture.handler.handleStandaloneElement(fixture.parse("<mytag />"));

    assertEquals(1, invocations.get());
    assertEvents(fixture, "standalone:mytag");
    assertEquals(0, fixture.context.level());
}


