@Test
@DisplayName("An attribute added by a processor is visible to a later processor and the delegated tag")
void processorAddedAttributeIsAppliedToDelegatedTag() {
    final Fixture fixture = new Fixture(false,
            elementTagProcessor("mytag", 10,
                    (context, tag, handler) -> handler.setAttribute("added", "value")),
            elementTagProcessor("mytag", 20, (context, tag, handler) -> {
                final IAttribute added = tag.getAttribute("added");
                assertEquals("value", added.getValue());
            }));

    fixture.handler.handleStandaloneElement(fixture.parse("<mytag />"));

    assertEquals(1, fixture.next.events.size());
    final IStandaloneElementTag delegated = assertInstanceOf(IStandaloneElementTag.class, fixture.next.events.get(0));
    assertEquals("value", delegated.getAttribute("added").getValue());
    assertEquals(0, fixture.context.level());
}



@Test
@DisplayName("Throttled rendering of several standalone elements produces the complete output across chunks")
void throttledEngineRenderingProducesCompleteOutput() {
    final TemplateEngine templateEngine = new TemplateEngine();
    templateEngine.setDialect(new TestDialect(
            elementTagProcessor("mytag", 10,
                    (context, tag, handler) -> handler.replaceWith("x", false))));
    final IThrottledTemplateProcessor processor =
            templateEngine.processThrottled("<mytag /><mytag /><mytag />", new Context());
    final StringWriter writer = new StringWriter();

    int guard = 0;
    while (!processor.isFinished()) {
        processor.process(1, writer);
        guard++;
        assertTrue(guard < 100, "Throttled processing should finish in a bounded number of chunks");
    }

    assertEquals("xxx", writer.toString());
}


private static IProcessor elementTagProcessor(
