    @Test
    public void insertBeforeModelIsDelegatedBeforeTheOpenTag() {

        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final ProcessorTemplateHandler handler = newHandler(next);

        final IElementProcessor processor = tagProcessor(100, new TagProcessorAction() {
            public void execute(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                final IModel before = modelFactory().createModel();
                before.add(modelFactory().createComment("before"));
