        });

        handler.handleOpenElement(openTag(elementDefinition(first, second), "id", "original"));

        assertEquals(Arrays.asList("open:div"), next.descriptions());

        final IOpenElementTag delegated = next.openTags().get(0);
        assertEquals("original", delegated.getAttributeValue("id"));
        assertEquals("first-original", delegated.getAttributeValue("data-order"));
        assertEquals("second-first-original", delegated.getAttributeValue("data-second"));
