    static IEngineContext newContext(final IEngineConfiguration configuration) {
        final TemplateData templateData =
                new TemplateData("testTemplate", null, new StringTemplateResource("<div></div>"), HTML, null);
        return new EngineContext(configuration, templateData, null, Locale.US, null);
    }

    static IEngineContext newContext() {
        return newContext(CONFIGURATION);
    }

    static IModelFactory modelFactory() {
        return CONFIGURATION.getModelFactory(HTML);
    }

    /**
     * Builds an element definition for the "div" element containing exactly the specified processors
     * (all of them must be element-oriented, i.e. matching the element name and not a specific attribute).
     */
    static ElementDefinition elementDefinition(final IElementProcessor... processors) {
        final Map<TemplateMode, Set<IElementProcessor>> processorsByTemplateMode =
                new EnumMap<TemplateMode, Set<IElementProcessor>>(TemplateMode.class);
        processorsByTemplateMode.put(HTML, new LinkedHashSet<IElementProcessor>(Arrays.asList(processors)));
        return new ElementDefinitions(processorsByTemplateMode).forName(HTML, DIV);
    }

    static IOpenElementTag openTag(final ElementDefinition elementDefinition) {
        return new OpenElementTag(HTML, elementDefinition, DIV, null, false);
    }

    static IOpenElementTag openTag(
            final ElementDefinition elementDefinition, final String attributeName, final String attributeValue) {
        final IOpenElementTag attributesSource =
                modelFactory().createOpenElementTag(DIV, attributeName, attributeValue);
        final Attributes attributes = ((AbstractProcessableElementTag) attributesSource).attributes;
        return new OpenElementTag(HTML, elementDefinition, DIV, attributes, false);
    }

    static ICloseElementTag closeTag() {
        return modelFactory().createCloseElementTag(DIV);
    }

    static IText text(final String content) {
        return modelFactory().createText(content);
    }

    static ProcessorTemplateHandler newHandler(final RecordingTemplateHandler next) {
        return newHandler(CONFIGURATION, newContext(CONFIGURATION), next, null);
    }

    static ProcessorTemplateHandler newHandler(
            final RecordingTemplateHandler next, final TemplateFlowController flowController) {
        return newHandler(CONFIGURATION, newContext(CONFIGURATION), next, flowController);
    }

    static ProcessorTemplateHandler newHandler(
            final IEngineConfiguration configuration, final IEngineContext context,
            final RecordingTemplateHandler next, final TemplateFlowController flowController) {
        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();
        handler.setNext(next);
        handler.setContext(context);
        if (flowController != null) {
            handler.setFlowController(flowController);
        }
        return handler;
    }

    static AbstractElementTagProcessor tagProcessor(final int precedence, final TagProcessorAction action) {
        return new AbstractElementTagProcessor(HTML, "tst", DIV, false, null, false, precedence) {

            @Override
            protected void doProcess(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                action.execute(context, tag, structureHandler);
            }

        };
    }

    static AbstractElementModelProcessor modelProcessor(final int precedence, final ModelProcessorAction action) {
        return new AbstractElementModelProcessor(HTML, "tst", DIV, false, null, false, precedence) {

            @Override
            protected void doProcess(
                    final ITemplateContext context,
                    final IModel model,
                    final IElementModelStructureHandler structureHandler) {
                action.execute(context, model, structureHandler);
            }

        };
    }

    interface TagProcessorAction {
        void execute(ITemplateContext context, IProcessableElementTag tag, IElementTagStructureHandler structureHandler);
    }

    interface ModelProcessorAction {
        void execute(ITemplateContext context, IModel model, IElementModelStructureHandler structureHandler);
    }


    /**
     * A template handler that simply records every event it receives, so that the effects of executing
     * {@link ProcessorTemplateHandler#handleOpenElement(IOpenElementTag)} can be verified.
     */
    static final class RecordingTemplateHandler implements ITemplateHandler {

        private final List<ITemplateEvent> events = new ArrayList<ITemplateEvent>();

        public void setNext(final ITemplateHandler next) {
            // Nothing to do
        }

        public void setContext(final ITemplateContext context) {
            // Nothing to do
        }

        public void handleTemplateStart(final ITemplateStart templateStart) {
            this.events.add(templateStart);
        }

        public void handleTemplateEnd(final ITemplateEnd templateEnd) {
            this.events.add(templateEnd);
        }

        public void handleXMLDeclaration(final IXMLDeclaration xmlDeclaration) {
            this.events.add(xmlDeclaration);
        }

        public void handleDocType(final IDocType docType) {
            this.events.add(docType);
        }

        public void handleCDATASection(final ICDATASection cdataSection) {
            this.events.add(cdataSection);
        }

        public void handleComment(final IComment comment) {
            this.events.add(comment);
        }

        public void handleText(final IText text) {
            this.events.add(text);
        }

        public void handleStandaloneElement(final IStandaloneElementTag standaloneElementTag) {
            this.events.add(standaloneElementTag);
        }

        public void handleOpenElement(final IOpenElementTag openElementTag) {
            this.events.add(openElementTag);
        }

        public void handleCloseElement(final ICloseElementTag closeElementTag) {
            this.events.add(closeElementTag);
        }

        public void handleProcessingInstruction(final IProcessingInstruction processingInstruction) {
            this.events.add(processingInstruction);
        }

        List<ITemplateEvent> getEvents() {
            return this.events;
        }

        List<String> descriptions() {
            final List<String> result = new ArrayList<String>(this.events.size());
            for (final ITemplateEvent event : this.events) {
                result.add(describe(event));
            }
            return result;
        }

        List<IOpenElementTag> openTags() {
            final List<IOpenElementTag> result = new ArrayList<IOpenElementTag>();
            for (final ITemplateEvent event : this.events) {
                if (event instanceof IOpenElementTag) {
                    result.add((IOpenElementTag) event);
                }
            }
            return result;
        }

    }


    static String describe(final ITemplateEvent event) {
        if (event instanceof IOpenElementTag) {
            return "open:" + ((IOpenElementTag) event).getElementCompleteName();
        }
        if (event instanceof IStandaloneElementTag) {
            return "standalone:" + ((IStandaloneElementTag) event).getElementCompleteName();
        }
        if (event instanceof ICloseElementTag) {
            return "close:" + ((ICloseElementTag) event).getElementCompleteName();
        }
        if (event instanceof IText) {
            return "text:" + ((IText) event).getText();
        }
        if (event instanceof IComment) {
            return "comment:" + ((IComment) event).getContent();
        }
        return event.getClass().getSimpleName();
    }


    /**
     * Dialect contributing a single text processor that uppercases the textual content it processes. It is
     * used for verifying whether the events queued by the handler are processed by the handler itself
     * ("processable" queues) or simply delegated to the next handler in the chain.
     */
    static final class UppercaseTextDialect extends AbstractDialect implements IProcessorDialect {

        UppercaseTextDialect() {
            super("test-uppercase-text");
        }

        public String getPrefix() {
            return "tst";
        }

        public int getDialectProcessorPrecedence() {
            return 0;
        }

        public Set<IProcessor> getProcessors(final String dialectPrefix) {
            final Set<IProcessor> processors = new LinkedHashSet<IProcessor>();
            processors.add(new AbstractTextProcessor(HTML, 100) {
                @Override
                protected void doProcess(
                        final ITemplateContext context, final IText text,
                        final ITextStructureHandler structureHandler) {
                    structureHandler.setText(text.getText().toUpperCase(Locale.US));
                }
            });
            return processors;
        }

    }


    static IEngineConfiguration configurationWithUppercaseTextProcessor() {
        final TemplateEngine engine = new TemplateEngine();
        engine.addDialect(new UppercaseTextDialect());
        return engine.getConfiguration();
    }


