    @Test
    public void setBodyTextReplacesBodyAndSkipsTheOriginalBodyContent() {

        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final ProcessorTemplateHandler handler = newHandler(next);

        final IElementProcessor processor = tagProcessor(100, new TagProcessorAction() {
            public void execute(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.setBody("replacement", false);
            }
        });

        handler.handleOpenElement(openTag(elementDefinition(processor)));

        assertEquals(Arrays.asList("open:div", "text:replacement"), next.descriptions());

        // The original body must be skipped (it was replaced by the processor)
        handler.handleText(text("original body"));
        assertEquals(Arrays.asList("open:div", "text:replacement"), next.descriptions());

        // ...and the close tag of the element is still processed
        handler.handleCloseElement(closeTag());
        assertEquals(Arrays.asList("open:div", "text:replacement", "close:div"), next.descriptions());
    }


