        final IEngineContext context = newContext(CONFIGURATION);
        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final ProcessorTemplateHandler handler = newHandler(CONFIGURATION, context, next, null);

        final List<Object> iteratedVariables = new ArrayList<Object>();

        final IElementProcessor iterator = tagProcessor(100, new TagProcessorAction() {
            public void execute(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.iterateElement("item", null, Arrays.asList("one", "two"));
            }
        });
        // Second processor executed on the iterated copies of the element (never on the original one)
        final IElementProcessor observer = tagProcessor(200, new TagProcessorAction() {
            public void execute(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                iteratedVariables.add(context.getVariable("item"));
            }
        });

        handler.handleOpenElement(openTag(elementDefinition(iterator, observer)));
        handler.handleText(text("body"));
        handler.handleCloseElement(closeTag());

        assertEquals(Arrays.asList("one", "two"), iteratedVariables);
    }


