    @Test
    public void openElementIsQueuedWhenProcessingIsStopped() {

        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final TemplateFlowController flowController = new TemplateFlowController();
        final ProcessorTemplateHandler handler = newHandler(next, flowController);

        flowController.stopProcessing = true;

        handler.handleOpenElement(openTag(elementDefinition()));

        assertTrue(next.descriptions().isEmpty());
        assertTrue(flowController.processorTemplateHandlerPending);

        // Once processing is resumed, the pending event is handled normally
        flowController.stopProcessing = false;
        handler.handlePending();

