    @Test
    public void openElementWithoutProcessorsIsDelegatedToNextHandler() {

        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final ProcessorTemplateHandler handler = newHandler(next);

        final IOpenElementTag tag = openTag(elementDefinition());

        handler.handleOpenElement(tag);

        assertEquals(Arrays.asList("open:div"), next.descriptions());
        assertEquals(tag, next.openTags().get(0));
    }


    @Test
    public void tagProcessorsAreExecutedInPrecedenceOrderAndModifyTheDelegatedTag() {

        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final ProcessorTemplateHandler handler = newHandler(next);

        final IElementProcessor first = tagProcessor(100, new TagProcessorAction() {
            public void execute(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.setAttribute("data-order", "first-" + tag.getAttributeValue("id"));
            }
        });
        final IElementProcessor second = tagProcessor(200, new TagProcessorAction() {
            public void execute(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.setAttribute("data-second", "second-" + tag.getAttributeValue("data-order"));
            }
        });

        handler.handleOpenElement(openTag(elementDefinition(first, second), "id", "original"));

        assertEquals(Arrays.asList("open:div"), next.descriptions());

        final IOpenElementTag delegated = next.openTags().get(0);
        assertEquals("original", delegated.getAttributeValue("id"));
        assertEquals("first-original", delegated.getAttributeValue("data-order"));
        assertEquals("second-first-original", delegated.getAttributeValue("data-second"));
    }


    @Test
    public void attributesCanBeRemovedFromTheDelegatedTag() {

        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        final ProcessorTemplateHandler handler = newHandler(next);

