@Test
public void modelProcessorReplacesTheGatheredModelWhenItIsModified() {

    final RecordingTemplateHandler next = new RecordingTemplateHandler();
    final ProcessorTemplateHandler handler = newHandler(next);

    // The processor only modifies the model the first time it is executed, so that the re-execution of the
    // modified model does not modify it again (which would restart the gathering process).
    final boolean[] modified = new boolean[] {false};
    final IElementProcessor processor = modelProcessor(100, new ModelProcessorAction() {
        public void execute(
                final ITemplateContext context,
                final IModel model,
                final IElementModelStructureHandler structureHandler) {
            model.insert(1, text("!"));
        }
            if (!modified[0]) {
                modified[0] = true;
                model.insert(1, text("!"));
            }

    handler.handleOpenElement(openTag(elementDefinition(processor)));
    handler.handleText(text("body"));
    handler.handleCloseElement(closeTag());

    // The modified model replaces the whole element (open tag, body, close tag)
    assertEquals(Arrays.asList("open:div", "text:!", "text:body", "close:div"), next.descriptions());
}


